{
  "claims": [
    {
      "claim": "Direct human and rat PET studies show that [11C]tariquidar, the radiolabeled form of the query molecule, has very low brain uptake and behaves as a P-gp/BCRP efflux substrate, indicating poor CNS access.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 3",
        "Molecule 19"
      ],
      "record_ids": [
        "Record 3-1",
        "Record 3-10",
        "Record 19-3"
      ]
    },
    {
      "claim": "A close fluoroethyl analog of the query ([18F]4) shows 8- to 9-fold higher brain AUC in P-gp/Bcrp knockout mice and ~7-fold higher uptake after P-gp/BCRP inhibition, demonstrating that efflux transporters severely restrict brain exposure of this chemotype in wild-type animals.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 18"
      ],
      "record_ids": [
        "Record 18-1",
        "Record 18-2",
        "Record 18-4"
      ]
    },
    {
      "claim": "Tariquidar is a substrate of ABCG2 but does not inhibit ABCG2, so even at pharmacological doses it cannot overcome BCRP-mediated efflux at the blood-brain barrier, further limiting meaningful CNS penetration.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 19"
      ],
      "record_ids": [
        "Record 19-2",
        "Record 19-3"
      ]
    },
    {
      "claim": "Some related tetrahydroisoquinoline radiotracers and a methyl ester analog show high brain uptake, but these lack the query's specific quinoline-3-carboxamide efflux-substrate pharmacophore or were only assessed by passive permeability, so they are less transferable and do not outweigh the direct efflux-limited brain exposure evidence.",
      "evidence_role": "contradictory",
